const { useEffect, useRef, useState } = React;

const KEYFRAMES = [
  { transform: "scale(1)", opacity: 1, offset: 0 },
  { transform: "scale(.5)", opacity: 0.5, offset: 0.3 },
  { transform: "scale(.667)", opacity: 0.667, offset: 0.7875 },
  { transform: "scale(.6)", opacity: 0.6, offset: 1 },
];
const DURATION = 700;

const Component = () => {
  const boxRef = useRef(null);
  const animationRef = useRef(null);
  const [playing, setPlaying] = useState(true);
  const [rate, setRate] = useState(1);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const animation = boxRef.current.animate(KEYFRAMES, {
      duration: DURATION,
      easing: "ease-in-out",
      delay: 10,
      iterations: Infinity,
      direction: "alternate",
      fill: "forwards",
    });
    animationRef.current = animation;
    // 逐帧读取当前进度，驱动下方进度条
    let frame = 0;
    const tick = () => {
      const time = Number(animation.currentTime) || 0;
      const cycle = Math.floor(time / DURATION);
      const local = (time % DURATION) / DURATION;
      setProgress(cycle % 2 ? 1 - local : local);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frame);
      animation.cancel();
    };
  }, []);

  const toggle = () => {
    const animation = animationRef.current;
    if (!animation) return;
    if (playing) animation.pause();
    else animation.play();
    setPlaying(!playing);
  };

  const changeRate = value => {
    setRate(value);
    animationRef.current?.updatePlaybackRate(value);
  };

  return (
    <div className="flex flex-col gap-3">
      <div className="flex h-[180px] items-center justify-center rounded-tau-md border border-line-1">
        <div ref={boxRef} className="size-[100px] rounded-tau-md bg-accent" />
      </div>
      <div className="h-1 overflow-hidden rounded-full bg-track">
        <div className="h-full rounded-full bg-accent" style={{ width: `${progress * 100}%` }} />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="secondary" size="sm" icon={playing ? icons.Pause : icons.Play} onClick={toggle}>
          {playing ? "pause()" : "play()"}
        </ui.Button>
        <ui.Button variant="ghost" size="sm" icon={icons.ArrowLeftRight} onClick={() => animationRef.current?.reverse()}>
          reverse()
        </ui.Button>
        <ui.Select
          size="sm"
          aria-label="playbackRate"
          options={[0.25, 0.5, 1, 2].map(value => ({ value, label: `playbackRate ${value}` }))}
          value={rate}
          onValueChange={changeRate}
          className="w-[180px]"
        />
      </div>
    </div>
  );
};
